export interface ClientState {
  token: string | null;
  screen: string;
  alert: string | null;
}

export interface ServiceReply {
  status: number;
  message: string;
}

export function applyServiceReply(
  state: ClientState,
  reply: ServiceReply,
): ClientState {
  if (
    typeof state !== "object" ||
    state === null ||
    (typeof state.token !== "string" && state.token !== null) ||
    typeof state.screen !== "string" ||
    typeof reply !== "object" ||
    reply === null ||
    !Number.isInteger(reply.status) ||
    reply.status < 100 ||
    reply.status > 599 ||
    typeof reply.message !== "string"
  ) {
    throw new TypeError("malformed state or reply");
  }

  if (reply.status >= 200 && reply.status < 300) {
    return { ...state, alert: null };
  }

  const alert = reply.message || `Request failed (${reply.status})`;
  return {
    ...state,
    token: null,
    screen: "catalog",
    alert,
  };
}
```

