import { applyServiceReply, type ClientState } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsType(fn: () => unknown, message: string): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof TypeError, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const state: ClientState = { token: "token-1", screen: "checkout", alert: "old" };
const success = applyServiceReply(state, { status: 200, message: "ignored" });
assert(success !== state, "success returns a fresh state");
equal(success.token, "token-1", "success retains token");
equal(success.screen, "checkout", "success retains screen");
equal(success.alert, null, "success clears alert");
equal(state.alert, "old", "success does not mutate input");

const upperSuccess = applyServiceReply(state, { status: 299, message: "" });
equal(upperSuccess.alert, null, "299 is successful");

const ordinaryFailure = applyServiceReply(state, { status: 500, message: "Server unavailable" });
equal(ordinaryFailure.token, "token-1", "ordinary failure retains token");
equal(ordinaryFailure.screen, "checkout", "ordinary failure retains screen");
equal(ordinaryFailure.alert, "Server unavailable", "ordinary failure uses message");

const fallback = applyServiceReply(state, { status: 300, message: "" });
equal(fallback.token, "token-1", "empty-message failure retains token");
equal(fallback.screen, "checkout", "empty-message failure retains screen");
equal(fallback.alert, "Request failed (300)", "empty message uses fallback alert");

const unauthorized = applyServiceReply(state, { status: 401, message: "Unauthorized" });
equal(unauthorized.token, null, "401 clears token");
equal(unauthorized.screen, "catalog", "401 changes screen");
equal(unauthorized.alert, "Unauthorized", "401 preserves non-empty message as alert");

const revoked = applyServiceReply(state, { status: 503, message: "SESSION_REVOKED" });
equal(revoked.token, null, "exact revoked message clears token");
equal(revoked.screen, "catalog", "exact revoked message changes screen");
equal(revoked.alert, "SESSION_REVOKED", "revoked message is the alert");

const nearMatch = applyServiceReply(state, { status: 403, message: "session_revoked" });
equal(nearMatch.token, "token-1", "non-exact revoked message retains token");
equal(nearMatch.screen, "checkout", "non-exact revoked message retains screen");

const catalogState: ClientState = { token: "x", screen: "catalog", alert: null };
const catalogResult = applyServiceReply(catalogState, { status: 401, message: "" });
equal(catalogResult.screen, "catalog", "catalog screen remains catalog");
equal(catalogResult.alert, "Request failed (401)", "401 empty message uses fallback");
equal(catalogState.token, "x", "failure does not mutate input token");

const malformed: Array<() => unknown> = [
  () => applyServiceReply(null as unknown as ClientState, { status: 200, message: "" }),
  () => applyServiceReply({ token: 4 as unknown as string, screen: "x", alert: null }, { status: 200, message: "" }),
  () => applyServiceReply({ token: null, screen: 4 as unknown as string, alert: null }, { status: 200, message: "" }),
  () => applyServiceReply(state, null as unknown as { status: number; message: string }),
  () => applyServiceReply(state, { status: 99, message: "" }),
  () => applyServiceReply(state, { status: 600, message: "" }),
  () => applyServiceReply(state, { status: 200.5, message: "" }),
  () => applyServiceReply(state, { status: 200, message: 4 as unknown as string }),
];
for (const malformedCall of malformed) throwsType(malformedCall, "malformed state or reply throws TypeError");

